function showToast(icon,text){if(typeof playSound==='function'){playSound(icon==='success'?'feedback_success':icon==='error'?'feedback_error':'feedback_warning');}
const isAdmin=window.location.pathname.startsWith('/admin');let isLight=false;if(isAdmin){isLight=document.documentElement.getAttribute('data-admin-mode')==='light'||(typeof getAdminAppearanceMode==='function'&&getAdminAppearanceMode()==='light');}else{isLight=document.documentElement.getAttribute('data-public-mode')==='light'||(typeof getPublicAppearanceMode==='function'&&getPublicAppearanceMode()==='light');}
const bg=isLight?'#FFFFFF':'rgba(8,10,16,0.97)';const color=isLight?'#0F172A':'#F8FAFC';const iconColor=icon==='success'?(isLight?'var(--color-success)':'var(--color-success)'):icon==='error'?(isLight?'var(--color-danger)':'var(--color-danger)'):icon==='warning'?(isLight?'var(--color-warning)':'var(--color-warning)'):(isLight?'#2563EB':'var(--color-accent)');Swal.fire({icon,text,toast:true,position:'top-end',showConfirmButton:false,timer:3500,timerProgressBar:true,background:bg,color:color,iconColor:iconColor});}